import React from 'react';
import { useNavigate } from 'react-router-dom';
import classicImg from '../assets/classic.png';
import modernImg from '../assets/modern.png';
import minimalImg from '../assets/minimal.png';
import creativeImg from '../assets/creative.png';

const templates = [
  { key: 'classic', name: 'Classic', img: classicImg },
  { key: 'modern', name: 'Modern', img: modernImg },
  { key: 'minimal', name: 'Minimal', img: minimalImg },
  { key: 'creative', name: 'Creative', img: creativeImg },
];

function TemplateGallery() {
  const navigate = useNavigate();
  const handleSelect = (key) => {
    localStorage.setItem('selectedTemplate', key);
    navigate('/builder');
  };
  return (
    <div className="template-gallery">
      <h2>Choose Your Resume Template</h2>
      <div className="template-gallery-list">
        {templates.map(t => (
          <div className="template-card" key={t.key} onClick={() => handleSelect(t.key)}>
            <img src={t.img} alt={t.name} className="template-img" />
            <div className="template-name">{t.name}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default TemplateGallery;
